import{_ as i,c as t,o as a,a9 as r}from"./chunks/framework.BXLNC15u.js";const h=JSON.parse('{"title":"Type Alias: DefinitionEventBridgeConfig","description":"","frontmatter":{},"headers":[],"relativePath":"api/@purista/core/type-aliases/DefinitionEventBridgeConfig.md","filePath":"api/@purista/core/type-aliases/DefinitionEventBridgeConfig.md","lastUpdated":1778834280000}'),n={name:"api/@purista/core/type-aliases/DefinitionEventBridgeConfig.md"};function o(s,e,l,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<p><a href="./../../../README.html"><strong>PURISTA API</strong></a></p><hr><p><a href="./../../../packages.html">PURISTA API</a> / <a href="./../README.html">@purista/core</a> / DefinitionEventBridgeConfig</p><h1 id="type-alias-definitioneventbridgeconfig" tabindex="-1">Type Alias: DefinitionEventBridgeConfig <a class="header-anchor" href="#type-alias-definitioneventbridgeconfig" aria-label="Permalink to “Type Alias: DefinitionEventBridgeConfig”">​</a></h1><blockquote><p><strong>DefinitionEventBridgeConfig</strong> = <code>object</code></p></blockquote><p>Defined in: <a href="https://github.com/puristajs/purista/blob/master/packages/core/src/core/types/DefinitionEventBridgeConfig.ts#L8" target="_blank" rel="noreferrer">core/types/DefinitionEventBridgeConfig.ts:8</a></p><p>Settings and advices for the event bridge, which are set in the command or subscription builder. The properties are advices and hints. It depends on the used event bridge implementation and underlaying message broker, if a specific property can be respected.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="autoacknowledge" tabindex="-1">autoacknowledge <a class="header-anchor" href="#autoacknowledge" aria-label="Permalink to “autoacknowledge”">​</a></h3><blockquote><p><strong>autoacknowledge</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/puristajs/purista/blob/master/packages/core/src/core/types/DefinitionEventBridgeConfig.ts#L20" target="_blank" rel="noreferrer">core/types/DefinitionEventBridgeConfig.ts:20</a></p><p>Send the acknowledge to message broker as soon as the message arrives</p><ul><li>defaults to true for commands</li><li>defaults to true for subscriptions</li></ul><hr><h3 id="consumerfailurehandling" tabindex="-1">consumerFailureHandling? <a class="header-anchor" href="#consumerfailurehandling" aria-label="Permalink to “consumerFailureHandling?”">​</a></h3><blockquote><p><code>optional</code> <strong>consumerFailureHandling?</strong>: <a href="./DefinitionEventBridgeConsumerFailureHandling.html"><code>DefinitionEventBridgeConsumerFailureHandling</code></a></p></blockquote><p>Defined in: <a href="https://github.com/puristajs/purista/blob/master/packages/core/src/core/types/DefinitionEventBridgeConfig.ts#L40" target="_blank" rel="noreferrer">core/types/DefinitionEventBridgeConfig.ts:40</a></p><p>Advisory retry and dead-letter handling for consumer-style registrations.</p><p>This is primarily relevant for subscriptions and other push consumers. Adapters may ignore or partially honor these settings when the provider lacks broker-side retry or dead-letter support.</p><hr><h3 id="durable" tabindex="-1">durable <a class="header-anchor" href="#durable" aria-label="Permalink to “durable”">​</a></h3><blockquote><p><strong>durable</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/puristajs/purista/blob/master/packages/core/src/core/types/DefinitionEventBridgeConfig.ts#L13" target="_blank" rel="noreferrer">core/types/DefinitionEventBridgeConfig.ts:13</a></p><p>Advise the underlaying message broker to store messages if no consumer is available. Messages will be send as soon as the service is able to consume.</p><hr><h3 id="shared" tabindex="-1">shared <a class="header-anchor" href="#shared" aria-label="Permalink to “shared”">​</a></h3><blockquote><p><strong>shared</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/puristajs/purista/blob/master/packages/core/src/core/types/DefinitionEventBridgeConfig.ts#L32" target="_blank" rel="noreferrer">core/types/DefinitionEventBridgeConfig.ts:32</a></p><p>If set to true, the event bridge is adviced to deliver one message to at least one consumer instance. True is the default value. If set to false, the event bridge is adviced to deliver one message to all consumer instances.</p><p>Use case: Receiving Info of message, which need to be passed to all instance to keep information in sync.</p><p>In serverless environments, this flag should not have any effect</p><h4 id="default" tabindex="-1">Default <a class="header-anchor" href="#default" aria-label="Permalink to “Default”">​</a></h4><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div>',33)])])}const f=i(n,[["render",o]]);export{h as __pageData,f as default};
